def main():
    target=ROOT/'translation/batches/420_fuuka_statuses.generated.json';assert not target.exists()
    catalog={r['key']:r for r in read(ROOT/'translation/catalog.working.json')};sources=defaultdict(list)
    for m,values in TEXT.items():
        assert len(values)==20
        s=f'export_base/battle/support/bsv108.bvp_({m:03}).BMD.json';doc=read(ROOT/s)
        for i,body in zip(IDS,values):
            r=catalog[f'{s}:{i}:0'];assert not r.get('translation');body+='\n'
            a=TOKEN.sub('',r['original']).splitlines();b=body.splitlines()
            assert len(b)<=len(a) and max(map(len,b))<=max(map(len,a)),(m,i,a,b)
            sources[s].append([i,0,doc['texts'][i]['id'],body])
    write(target,dict(status='draft',sources=dict(sources),source_hashes={s:hashlib.sha256((ROOT/s).read_bytes()).hexdigest() for s in sources},review_notes=['风花054—060七组有效140页，保留占位；花村/巽/天田及真田/桐条/荒垣前辈按原文称呼。','保留石化忠犬调侃、睡眠防御下降描述；麻痹为可能不能行动，诅咒为主动攻击伤及自身。未运行验证。']))
    print('Fuuka status pages:',sum(map(len,sources.values())))

if __name__=='__main__':main()
